    button('編集点の操作を終了',()=>{stopHandles();status.textContent='キャンバス上の編集点を閉じました。';},status),
    toolConfirmation(button('適用',async()=>{
      if(api.context()?.drawing!==draftDrawing)throw Error('作品を開き直したため、「新しく作る」か「選んだレイヤーを編集」を選んでください。');
